    data = input().split()
    N = int(data[0])
    adj = [[] for _ in range(N + 1)]
    index = 1
    for _ in range(N - 1):
        u = int(data[index])
        v = int(data[index + 1])
        adj[u].append(v)
        adj[v].append(u)
        index += 2

    # Compute subtree sizes using iterative DFS
    subtree_size = [0] * (N + 1)
    stack = [(1, -1, False)]
    while stack:
        u, parent, visited = stack.pop()
        if not visited:
            stack.append((u, parent, True))
            for v in adj[u]:
                if v != parent:
                    stack.append((v, u, False))
        else:
            size = 1
            for v in adj[u]:
                if v != parent:
                    size += subtree_size[v]
            subtree_size[u] = size

    children = adj[1]
    k = len(children)
    if k == 0:
        print(1)
    else:
        sizes = [subtree_size[v] for v in children]
        if k == 1:
            print(1)
        else:
            sizes.sort()
            total = sum(sizes[:-1])
            print(total + 1)

