import sys

def main():
    import sys
    input = sys.stdin.read
    data = input().split()
    N = int(data[0])
    A = list(map(int, data[1:N+1]))

    first_occurrence = {}
    last_occurrence = {}

    for i in range(N):
        if A[i] not in first_occurrence:
            first_occurrence[A[i]] = i + 1  # 1-based index
    for i in range(N-1, -1, -1):
        if A[i] not in last_occurrence:
            last_occurrence[A[i]] = i + 1  # 1-based index

    D = len(set(A))

    delta = [0] * (N + 2)  # 1-based to N-1

    for x in set(A):
        f = first_occurrence[x]
        l = last_occurrence[x]
        a = f + 1
        b = l
        lower = max(a, 1)
        upper = min(b, N-1)
        if lower > upper:
            continue
        delta[lower] += 1
        if upper + 1 <= N:
            delta[upper + 1] -= 1

    current_sum = 0
    max_c = 0
    for j in range(1, N):
        current_sum += delta[j]
        if current_sum > max_c:
            max_c = current_sum

    print(D + max_c)

if __name__ == "__main__":
    main()
